double LabelStockDescriptor::getWidthInUnits(LabelWidth myWidth, bool isMetric)
{
	double rv = UnknownLabelInches;

	if (myWidth == NarrowLabel)
	{
		rv = NarrowLabelInches;
	}
	else if (myWidth == WideLabel)
	{
		rv = WideLabelInches;
	}
	else if (myWidth == UFWLabel)
	{
		rv = UFWLabelInches;
	}

	if (isMetric == true)
	{
		rv *= 25.4;
	}

	return rv;
}

bool LabelStockDescriptor::isPrintable(LabelStockDescriptor *stockToCompare) const
{
	bool rv = false;

	// compare widths in dots
	UINT16 numDots = stockToCompare->getWidthDots();

	if (numDots <= widthDots)
	{
		// compare Lengths in rows
		UINT16 numRows = stockToCompare->getLength();

		if (numRows <= length)
		{
			rv = true;
		}
	}

	return rv;
}

bool LabelStockDescriptor::isExactMatch(HfcPrinterStockMetrics *printerStockMetrics) const
{
	bool rv = false;
	LabelLength myLabelLength, stockLength;
	LabelWidth	myLabelWidth, stockWidth;

	// FT-599: need to check label width when continuous stock
	// the printerStockMetrics passed in is the metrics for the label stock loaded in the printer.
	//if (printerStockMetrics->isContinuousStock())
	//	return true;

	myLabelLength = PrinterStockMetrics::getLabelLength(length);
	stockLength = PrinterStockMetrics::getLabelLength(printerStockMetrics->getLabelLengthInLines());
	if ((myLabelLength == stockLength) || (printerStockMetrics->isContinuousStock())) // FT-599
	{
		myLabelWidth = PrinterStockMetrics::getLabelWidth(widthDots);
		stockWidth = PrinterStockMetrics::getLabelWidth(printerStockMetrics->getLabelWidthInDots());
		if (myLabelWidth == stockWidth)
		{
			rv = true;
		}
	}

	return rv;
}

void LabelStockDescriptor::writeBinaryData(Blob& binaryData)
{
	UINT16 temp = binaryData.ShortSwapBytes(widthDots);
	binaryData.append(temp);

	temp = binaryData.ShortSwapBytes(length);
	binaryData.append(temp);

	temp = binaryData.ShortSwapBytes(labelOrientationDegrees);
	binaryData.append(temp);

	temp = binaryData.ShortSwapBytes(skew);
	binaryData.append(temp);
}

